entries[232526] = { ["name"] = "Best-in-Slots", ["text"] = "Binds when picked up\nUnique-Equipped\nTwo-Hand Mace\n7,750 - 9,965 Damage Speed 3.60\n(2,460 damage per second)\n+3,269 [Agility or Strength]\n+19,463 Stamina\nDurability 120 / 120\nEquip: Your spells and abilities have a chance to grant you [source value] to [source value] of a random secondary stat for 15 sec.\nUse: Cheat to immediately gain [source value] of your highest secondary stat for 15 sec. While out of combat, reconfigure for spell casting instead. (2 Min Cooldown)\nDefeat One-Armed Bandit in Liberation of Undermine on Mythic difficulty.\n\"The wise goblin makes their own luck.\"\nSell Price:", ["unresolvedValues"] = true }
entries[232527] = { ["name"] = "Glyph of Traditional Ascendance", ["text"] = "Binds when picked up\nClasses: Shaman\nUse: Permanently teaches you this glyph.\n\nYour Ascendance transformations embody their traditional forms.\nSell Price:" }
entries[232531] = { ["name"] = "Grunch", ["text"] = "Binds to Warband\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 80 ( 80)" }
entries[232532] = { ["name"] = "Contract: The Cartels of Undermine", ["text"] = "Use: Sign a contract with The Cartels of Undermine that allows you to gain 5 reputation with them every time you complete a world quest in Khaz Algar until the next weekly reset.\n\nWarband Contract\nYou may only sign one contract per week. This effect is shared across your Warband.\n\"A document drafted by Scribes pledging a Warband's allegiance to a faction.\"\nSell Price:" }
entries[232533] = { ["name"] = "Contract: The Cartels of Undermine", ["text"] = "Use: Sign a contract with The Cartels of Undermine that allows you to gain 10 reputation with them every time you complete a world quest in Khaz Algar.\n\nWarband Contract\nYou may only sign one contract per week. This effect is shared across your Warband.\n\"A document drafted by Scribes pledging a Warband's allegiance to a faction.\"\nSell Price:" }
entries[232534] = { ["name"] = "Contract: The Cartels of Undermine", ["text"] = "Use: Sign a contract with The Cartels of Undermine that allows you to gain 15 reputation with them every time you complete a world quest in Khaz Algar.\n\nWarband Contract\nYou may only sign one contract per week. This effect is shared across your Warband.\n\"A document drafted by Scribes pledging a Warband's allegiance to a faction.\"\nSell Price:" }
entries[232535] = { ["name"] = "Technique: Contract: The Cartels of Undermine", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Contract: The Cartels of Undermine.\nRequires Khaz Algar Inscription (35)\nRequires Khaz Algar Inscription and Renown Rank 5 with the Cartels of Undermine.\nSell Price:" }
entries[232541] = { ["name"] = "Improvised Seaforium Pacemaker", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,508 [Agility or Strength]\nEquip: Repurpose a Seaforium charge to give your heart a kick, causing your first ability every 60 sec to trigger Explosive Adrenaline, granting 2624 Critical Strike for 15 sec.\n\nWhile exploding, Critical Strikes cause you to blow up again, extending this duration by 1 sec, up to 15 times.\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nComplete Operation: Floodgate within the time limit at keystone level 12 or higher during the War Within Season Three.\n\"It's just crazy enough to work...\"\nSell Price:" }
entries[232542] = { ["name"] = "Darkfuse Medichopper", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,508 Intellect\nUse: Command the Medichopper to attach to your target, absorbing 155184 damage and granting them 1375 versatility for 15 sec.\n\nWhile attached, your healing spells have a chance to refuel the chopper, granting these bonuses to their host again. (2 Min Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nComplete Operation: Floodgate within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:" }
entries[232543] = { ["name"] = "Ringing Ritual Mud", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 1,426 Versatility\nUse: Become Mudborne, absorbing 7088217 damage and pulsing ( 69870 * 10 / 2) Nature damage split between nearby enemies over 10 sec.\n\nPeriodic damage you take coalesces into pungent mud to feed the ritual, reducing this cooldown by [2][2.0] sec. (2 Min Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nComplete Operation: Floodgate within the time limit at keystone level 12 or higher during the War Within Season Three.\n\"Fear the old mud.\"\nSell Price:" }
entries[232545] = { ["name"] = "Gigazap's Zap-Cap", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,508 Intellect\nEquip: Every 6 sec, Zap your target and 1 nearby enemy for ( 34365 * 1 ) Nature damage.\n\nCasting 30 spells Turbo-Charges you for 15 sec, doubling the frequency of your Zaps and upgrading them into Giga-Zaps, dealing ( 34365 * 3 * 1 ) Nature Damage instead. (500ms cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nComplete Operation: Floodgate within the time limit at keystone level 12 or higher during the War Within Season Three.\nSell Price:" }
entries[232546] = { ["name"] = "K.U.-J.0.'s Flame Vents", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+3,508 [Agility or Strength]\nUse: Channel to vent flames for 2 sec, dealing [source value] Fire damage split between all nearby enemies.\n\nMechanical enemies become Superheated, taking 90352 additional Fire damage when struck by your next harmful ability. (2 Min Cooldown)\nComplete all Mythic+ dungeons within the time limit at keystone level 12 during The War Within Season 2.\nSell Price:", ["unresolvedValues"] = true }
