entries[232622] = { ["name"] = "Glyph of Energetic Ascendance", ["text"] = "Binds when picked up\nClasses: Shaman\nUse: Permanently teaches you this glyph.\n\nYour Ascendance transformations embody energetic forms, unleashing their power.\nSell Price:" }
entries[232623] = { ["name"] = "Ve'nari's Package", ["text"] = "Quest Item\nUnique\n\"Ve'nari has included both a cage and a portation tag that is tied to it. Simply put the tag on the target and they will be instantly teleported into the cage.\"" }
entries[232624] = { ["name"] = "Timely Buzzbee", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Buzzing through the time punctual as ever, these Buzzbees harvest the errant sands of time and return them safely to the Timeways.\"\nVendor:\nAny Timewalking Vendor\nCost:\n5000" }
entries[232625] = { ["name"] = "Wastelander Artifact", ["text"] = "Quest Item\n\"A small gem on a delicate chain.\"" }
entries[232626] = { ["name"] = "Wastelander Artifact", ["text"] = "Quest Item\n\"Carefully sealed scrolls.\"" }
entries[232627] = { ["name"] = "Wastelander Artifact", ["text"] = "Quest Item\n\"A curious device of unknown purpose.\"" }
entries[232628] = { ["name"] = "Wastelander Artifact", ["text"] = "Quest Item\n\"To the Wastelanders, these are priceless. To a collector, the value is a bit more negotiable.\"" }
entries[232629] = { ["name"] = "Distilled Knowledge of Timeways", ["text"] = "Binds to Warband\nUnique (5)\nUse: Increases experience gained from killing monsters and completing quests by 5%.\n\nCompleting Timewalking dungeons increases the effect and refreshes the duration.\n\nUpon reaching 4 applications, transforms to Mastery of Timeways , increasing that effect to 30%." }
entries[232630] = { ["name"] = "Xy Imports Ledger", ["text"] = "Quest Item\n\"The most recent iteration of the Xy Imports ledger. Holds information regarding day-to-day business operations.\"" }
