entries[232639] = { ["name"] = "Thrayir, Eyes of the Siren", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"In a fit of rage and despair, Thrayir conjured a storm that would ravage the land and annihilate Cyrce's enemies. After nearly ten thousand years, the seafury tempest continues to roil as an echo of his power.\"\nZone:\nSiren Isle" }
entries[232643] = { ["name"] = "Mysterious Tattered Journal", ["text"] = "Quest Item\n\"A stained and tattered journal that seems to be missing most of its pages.\"" }
entries[232644] = { ["name"] = "Broker Disguise Pin", ["text"] = "Quest Item\nUnique\nUse: Take on the appearance of a Xy Imports employee.\n\"A nondescript metal pin with the subtle touch of well-practiced illusion magic.\"" }
