entries[232804] = { ["name"] = "Capo's Molten Knuckles", ["text"] = "Binds when picked up\nUnique-Equipped\nOne-Hand Fist Weapon\n24 - 34 Damage Speed 2.60\n(11.2 damage per second)\n+10 [Agility or Strength]\n+28 Stamina\nDurability 80 / 80\nEquip: Gain a high chance to follow up your attacks with a fiery gilded uppercut, dealing ( 1218 * 1 ) Fire damage to your target. Molten gold continues to splatter to deal ( 68 * 1 * 5) Fire damage over 5 sec to all nearby enemies. Damage reduced beyond 8 enemies.\nDefeat Mug'Zee in Liberation of Undermine on Mythic difficulty.\nSell Price:" }
entries[232805] = { ["name"] = "Best-in-Slots", ["text"] = "Binds when picked up\nUnique-Equipped\nTwo-Hand Mace\n23 - 30 Damage Speed 3.60\n(7.4 damage per second)\n+88 Intellect\n+55 Stamina\nDurability 120 / 120\nEquip: Your spells and abilities have a chance to grant you [source value] to [source value] of a random secondary stat for 15 sec.\nUse: Cheat to immediately gain [source value] of your highest secondary stat for 15 sec. While out of combat, reconfigure for melee combat instead. (2 Min Cooldown)\n\"The wise goblin makes their own luck.\"\nSell Price:", ["unresolvedValues"] = true }
entries[232806] = { ["name"] = "Tiny Torq", ["text"] = "Binds when picked up\nUse: Teaches you how to summon Tiny Torq, whose dad could TOTALLY beat up Flarendo's dad.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)\nRequires Renown Rank 9 with the Gallagio Loyalty Rewards Club." }
