entries[232875] = { ["name"] = "Spark of Radiance", ["text"] = "Midnight Season 1\nBinds when picked up\nOptional Crafting Reagent\n\n\"A unique crafting material that radiates fierce light. Obtained through weekly quests or end-game activities, it is used to create the most powerful of equipment via professions.\"\nSell Price:" }
