entries[232883] = { ["name"] = "Turbo-Drain 5000", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+18 [Agility or Strength or Intellect]\nEquip: Your harmful spells and abilities have a chance to drain your target's electrical power, dealing ( 973 * 1 ) Nature damage over 5 sec. If the target dies while being drained, you gain 25% movement speed for 5 sec.\n\"The 8th Rule of Commerce: Fast goblins are smart goblins!\"\nSell Price:" }
