entries[232891] = { ["name"] = "Amorphous Relic", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\nEquip: Upon entering combat, and every 60 sec, gain either Massive or Miniature for 30 sec.\n\nMiniature\nReduces your size by 20%, and increases your Speed by 17 and Haste by 116 .\n\nMassive\nIncreases your size by 20%, maximum health by 753 , and Primary Stat by 27 .\nSell Price:" }
entries[232895] = { ["name"] = "Spotty", ["text"] = "Binds when picked up\nUse: Teaches you how to summon this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)" }
entries[232897] = { ["name"] = "Blood-B-Gone", ["text"] = "Quest Item\nUse: Throw an experimental detergent grenade to hopefully break up a blood monstrosity. (6 Sec Cooldown)" }
entries[232898] = { ["name"] = "Delver's Bounty", ["text"] = "Requires level 70 to 80 ( 80)\n\"There is a small chance to find a Delver's Bounty inside one of this delve's Heavy Trunks.\"" }
entries[232901] = { ["name"] = "Lunar Launcher", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"It's always a festival when you are on the Lunar Launcher.\"\nVendor:\nLunar Festival" }
entries[232902] = { ["name"] = "Spy-Copter Footage Roll", ["text"] = "Quest Item\n\"Extensive footage of the Venture Company's internal disputes.\"" }
entries[232903] = { ["name"] = "Jang'thraze the Protector", ["text"] = "Binds when picked up\nUnique-Equipped\nOne-Hand Sword\n3 - 6 Damage Speed 2.60\n(1.7 damage per second)\n+2 Strength\n+3 Stamina\nDurability 90 / 90\nEquip: Your melee attacks have a chance to grant a shield, absorbing ( 175 + 27 ) Physical damage. Lasts 20 sec.\nSell Price:" }
entries[232904] = { ["name"] = "Sul'thraze the Lasher", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Sword\n6 - 11 Damage Speed 3.60\n(2.4 damage per second)\n+5 Stamina\n+ 2 Haste\n+ 5 Versatility\nDurability 100 / 100\nEquip: Your melee attacks have a chance to lash the enemy with the rage of Sul'thraze, lowering the target's damage by [abs( 19 + 1 )], dealing [source value] Shadow damage, and another [source value] damage over 15 sec.", ["unresolvedValues"] = true }
entries[232905] = { ["name"] = "Malown's Slam", ["text"] = "Binds when picked up\nUnique-Equipped\nTwo-Hand Mace\n7 - 10 Damage Speed 3.60\n(2.4 damage per second)\n+ 4 Haste\n+ 3 Versatility\nDurability 100 / 100\nEquip: Your attacks have a chance to increase your Strength by 4 for 30 sec.\nSell Price:" }
