entries[232926] = { ["name"] = "Love Witch's Sweeper", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable magical broom! This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The original design of the feeling-fueled magic broom series \"Motion By Emotion\", this ride is sure to get you there in a swiffy!\"\nWorld Event:\nLove is in the Air\nDrop:\nApothecary Hummel" }
entries[232930] = { ["name"] = "Zaps Leadfoot", ["text"] = "Binds when picked up\nUnique\nUse: Employ this Venture Co. employee to increase the available time during Time Trials." }
entries[232932] = { ["name"] = "Brann Bronzebeard's Mace", ["text"] = "Main Hand Mace\n1 Damage Speed 1.40\n(0.7 damage per second)\nSell Price:" }
entries[232933] = { ["name"] = "Ensemble: Sky Witch's Heartfelt Shoulders", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Sky Witch's Heartfelt Shoulders.\n\"Includes a set of spaulders and shoulder capes in sky blue.\"" }
entries[232934] = { ["name"] = "Ensemble: Twilight Witch's Heartfelt Shoulders", ["text"] = "Binds to Warband\nUse: Collect the appearances of the Twilight Witch's Heartfelt Shoulders.\n\"Includes a set of spaulders and shoulder capes in deep violet.\"" }
entries[232935] = { ["name"] = "Vantus Rune: Liberation of Undermine", ["text"] = "Use: Once per week, attune yourself to the energies of the targeted Undermine raid boss and gain the following aura:\n\nVantus Rune: Liberation of Undermine\nIncrease your Versatility by 24 when fighting the targeted raid boss. This effect lasts the entire week.\nSell Price:" }
entries[232936] = { ["name"] = "Vantus Rune: Liberation of Undermine", ["text"] = "Use: Once per week, attune yourself to the energies of the targeted Undermine raid boss and gain the following aura:\n\nVantus Rune: Liberation of Undermine\nIncrease your Versatility by 107 when fighting the targeted raid boss. This effect lasts the entire week.\nSell Price:" }
entries[232937] = { ["name"] = "Vantus Rune: Liberation of Undermine", ["text"] = "Use: Once per week, attune yourself to the energies of the targeted Undermine raid boss and gain the following aura:\n\nVantus Rune: Liberation of Undermine\nIncrease your Versatility by 27 when fighting the targeted raid boss. This effect lasts the entire week.\nSell Price:" }
entries[232944] = { ["name"] = "Ethereal Warning Letter", ["text"] = "Quest Item\nUnique\n\"Don't worry about the bots at the pickup. Last guy spotted an ethereal watchin' us, and it ain't the first. These bots'll make sure no one gets the drop on ya.\"" }
entries[232946] = { ["name"] = "Verus", ["text"] = "Binds when picked up\nUnique\nOff Hand Warglaive\n4 - 9 Damage Speed 2.60\n(2.5 damage per second)\n+12 Intellect\n+3 [Agility or Intellect]\n+4 Stamina\n+ 3 Critical Strike\n+ 2 Mastery\n\nPrismatic Socket\nPrismatic Socket\nPrismatic Socket" }
entries[232978] = { ["name"] = "Louie Firehands", ["text"] = "Binds when picked up\nUnique\nUse: Employ this Blackwater employee to provide an emergency explode button to your Breakneck." }
entries[232979] = { ["name"] = "Jaks Jabberjaw", ["text"] = "Binds when picked up\nUnique\nUse: Employ this Bilgewater employee who can slow enemies from the back of your Breakneck." }
entries[232980] = { ["name"] = "Axel Sneakfoot", ["text"] = "Binds when picked up\nUnique\nUse: Employ this Steamwheedle employee to provide temporary cover to your Breakneck." }
entries[232981] = { ["name"] = "GNZ Airmaster 9000", ["text"] = "Binds when picked up\nUse: Install this engine to increase the top speed of your G-99 Breakneck at the cost of acceleration.\nRequires Renown Rank 19 with the Cartels of Undermine.\n\"That block's got cylinders with 80 millimeter bores and puts out 35,000 horses.\"" }
entries[232982] = { ["name"] = "The Pozzik Standard", ["text"] = "Binds when picked up\nUse: Install this engine to increase the acceleration rate of your G-99 Breakneck at the cost of top speed.\n\"When the Mirage Raceway was destroyed during the cataclysm, Pozzik needed a new place to refine his craft.The Undermine proved fertile grounds for an automatic revolution.\"" }
entries[232983] = { ["name"] = "Steamboil", ["text"] = "Binds when picked up\nUse: Install this turbo to give your G-99 Breakneck a burst of speed. This turbo has a higher top speed at the cost of efficiency.\n\"They say when it's burned as fuel it releases one hundred times more energy than gold nitro.\"\nSell Price:" }
entries[232984] = { ["name"] = "Handcrank", ["text"] = "Binds when picked up\nUse: Install this turbo to give your G-99 Breakneck a burst of speed. This turbo is more efficient at the cost of top speed.\n\"There's nothing more effcient than some good old elbow grease.\"\nSell Price:" }
entries[232985] = { ["name"] = "22H Slicks", ["text"] = "Use: Install these wheels to increase the turning capability of your G-99 Breakneck at the cost of drifting stabilization.\n\"Full surface contact for maximum friction.\"\nSell Price:" }
entries[232986] = { ["name"] = "GE86 Advance", ["text"] = "Binds when picked up\nUse: Install these wheels to increase the drifting stability of your G-99 Breakneck at the cost of turning capability.\n\"For drivers who like to take long turns at the beach.\"" }
entries[232987] = { ["name"] = "Brann Bronzebeard's Shield", ["text"] = "Main Hand\n1 Damage Speed 3.00\n(0.3 damage per second)\nSell Price:" }
entries[232988] = { ["name"] = "Void Tear", ["text"] = "Off-Hand\nUnique-Equipped\nEquipable Spell - Utility" }
entries[232989] = { ["name"] = "S4F3-T Inspectors", ["text"] = "Quest Item\nUse: Equip the goggles, allowing you to identify nearby building code violations in Hovel Hill." }
entries[232990] = { ["name"] = "Bug Bits", ["text"] = "Quest Item\n\"These bug bits have been chopped up as finely as possible.\"" }
entries[232991] = { ["name"] = "The Breaker's Song", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses The Breaker's Song.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"'Tis a rare moment in history when a sailor carves the very monster that left 'em stranded to die upon the bow of their ship. Our lot is a blasphemous and piddly bunch. To think one of us might have the humility to honor such a creature is damn near mad.\"\nZone:\nSiren Isle\nAchievement:\nIsle Remember You" }
entries[232992] = { ["name"] = "Large Bug Bits", ["text"] = "Quest Item\nUse: Chop a large bug bit into 5 smaller bug bits. A pity Rhubarn never specified the size of the bug bits. Such a shame.\n\"A very meaty and slimy portion of bug meat.\"" }
entries[233006] = { ["name"] = "Container of Highly Profitable Sludge", ["text"] = "\"This stuff smells funky and sloshes around in the container. Maybe don't drop it?\"" }
entries[233007] = { ["name"] = "Crate of Somewhat Profitable Sludge", ["text"] = "\"It doesn't feel that heavy, but definitely has some heft once you lug it around. Yet the burden must continue.\"" }
entries[233008] = { ["name"] = "Box of Lightly Profitable Sludge", ["text"] = "\"These small amounts don't seem like much, but in the big picture they really add up.\"" }
entries[233009] = { ["name"] = "Firebud Pollen", ["text"] = "Quest Item\n\"This pollen is uncharacteristically warm to the touch.\"" }
entries[233010] = { ["name"] = "Rak-ush Mushroom", ["text"] = "Quest Item\n\"A weighty mushroom that crumbles slightly when touched. It smells vaguely like cinnamon, of all things.\"" }
entries[233011] = { ["name"] = "Voshshroom", ["text"] = "Quest Item\n\"A very rare mushroom, apparently. It smells like a cross between dirt and mushroom.\"" }
entries[233013] = { ["name"] = "Coal Cookie", ["text"] = "Binds when picked up\nUse: Restores ( 33750 / 5 * 25) health and ( 45000 / 5 * 25) mana over 25 sec. Must remain seated while eating." }
entries[233014] = { ["name"] = "Bronze Celebration Cache of Treasures", ["text"] = "Binds when picked up\n\"Weekly cache containing materials for upgrading gear, gold, and more.The first weekly cache you earn each week contains a piece of Champion gear from Blackrock Depths and a Restored Coffer Key. Subsequent caches contain a piece of Veteran gear.\"\n<Right Click to Open>" }
entries[233015] = { ["name"] = "Metal Scrap", ["text"] = "Quest Item\n\"Salvaged from broken machines and weapons, often used by tinkerers and engineers to craft or repair gadgets, armor, and various mechanical devices.\"" }
entries[233016] = { ["name"] = "Creature Bones", ["text"] = "Quest Item\n\"A collection of bones from animals in K'aresh.\"" }
entries[233018] = { ["name"] = "Essence Collector", ["text"] = "Quest Item\n\"Thick metal bars curve around a crackling violet core of energy. The collector thrums and pulses, sending an electric feeling up your arm.\"" }
entries[233019] = { ["name"] = "Sky Witch's Sweeper", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable magical broom! This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The sky's the limit when you mount up on this \"Motion By Emotion\" magic broom model.\"\nIn-Game Shop" }
entries[233020] = { ["name"] = "Twilight Witch's Sweeper", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable magical broom! This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"A darker look for the \"Motion By Emotion\" magic broom series of mounts. Fans of this color know that it looks good regardless of the time of day.\"\nIn-Game Shop" }
entries[233021] = { ["name"] = "Grappling-Grabber 9000", ["text"] = "\"This gadget will allow you to grab goblins and explosives from a distance!\"" }
entries[233022] = { ["name"] = "Technique: Vantus Rune: Liberation of Undermine", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Vantus Rune: Liberation of Undermine.\nRequires Khaz Algar Inscription (35)\nRequires Khaz Algar Inscription and Renown Rank 5 with the Cartels of Undermine.\nSell Price:" }
entries[233023] = { ["name"] = "Silvermoon Sweeper", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable magical broom! This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"The Silvermoon color scheme for the \"Motion By Emotion\" has been a success all across Azeroth.\"\nTrading Post" }
entries[233025] = { ["name"] = "Giant Pile of Gold", ["text"] = "\"This is a real haul! Who knew some nerubians carried this much gold?\"" }
entries[233026] = { ["name"] = "Johnny's Share of the Spoils", ["text"] = "\"This might cover Johnny's repair cost.\"" }
entries[233027] = { ["name"] = "Well Loved Squeaky Toy", ["text"] = "Binds when picked up\n\"Caked in layers of dust this toy still squeaks gently when squeezed.\"" }
entries[233028] = { ["name"] = "Flamethrower", ["text"] = "Quest Item\nUse: The broker's fire burns simultaneously in multiple energy spectrums. (10 Sec Cooldown)\n\"Sometimes, fire is the answer.\"" }
