entries[233055] = { ["name"] = "Corpse Cleaner", ["text"] = "Binds to Warband\nUse: Throw this onto an enemy corpse dissolving them into a pool of ooze and ingenuity! Enemies within the 5 yard radius will take 72556 Nature damage every 2 seconds over 20 sec.\n\nOnly usable in delves and outdoors in Khaz Algar. (5 Min Cooldown)\n\"Melts away those pesky corpses for easy cleaning!\"\nSell Price:" }
entries[233056] = { ["name"] = "Marmaduke", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)\nSell Price:" }
entries[233057] = { ["name"] = "Rock Hound Mica", ["text"] = "Binds when picked up\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)\nSell Price:" }
entries[233058] = { ["name"] = "Soweezi's Vintage Waveshredder", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses Soweezi's Vintage Waveshredder. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"This pretty lil' thing has a beautiful platinum sheen. It'll take ya sky-high in seconds! You'll be dancing around the sun to your heart's content for the low, low price of ten thousand smackeroonies.\"\nZone:\nSiren Isle\nVendor:\nSoweezi" }
entries[233061] = { ["name"] = "Rock-in-a-Bottle", ["text"] = "Binds to Warband\nUse: The complex engineering behind how such a large rock ended up in such a small bottle is a mystery to you, but your target enemy might have an idea. Stun it for 3 sec.\n\nOnly usable inside of Delves. (1 Min Cooldown)\n\"A big rock surrounded by a glass bottle.\"\nSell Price:" }
entries[233062] = { ["name"] = "Pocket Pizza", ["text"] = "Binds to Warband\nUse: Restores ( 9025 / 5 * 20) health over 20 sec. Must remain seated while eating.\n\nGreasy Well Fed\nIf you spend at least 10 seconds eating you will become Greasy Well Fed and gain ( 16 * 1.5) of your highest secondary and lose 5% movement speed.\n\nOnly usable in delves and outdoors in Khaz Algar.\n\"Kept safe in its Venture Co. Pizza Pouch.\"\nSell Price:" }
entries[233063] = { ["name"] = "Brann's Boomstick", ["text"] = "Binds when picked up\nRanged Gun\n1 Damage Speed 3.00\n(0.3 damage per second)\nSell Price:" }
entries[233064] = { ["name"] = "Bronze Goblin Waveshredder", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses a Goblin Wave Shredder. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Even cartel employees deserve to have some R&R on occassion.\"\nDrop:\nDarkfuse Trove\nZone:\nUndermine" }
entries[233066] = { ["name"] = "Radioactive Rat's Head", ["text"] = "Quest Item\nUnique\n\"Dripping with blood and glowing dangerously, you hope it's safe enough to stash in your bag.\"" }
entries[233068] = { ["name"] = "Rod of Analysis", ["text"] = "Quest Item\nRequires level 80 to 80 ( 80)\n\"This fragile crystal rod is one of many types of activation rods. This particular one analyzes data to properly restart a control console.\"" }
entries[233071] = { ["name"] = "Delver's Bounty", ["text"] = "The War Within Season 2\nBinds when picked up\nUnique\n\"Surely, great treasure awaits.\"\nSell Price:" }
