entries[233186] = { ["name"] = "Wave Scrambler 2000", ["text"] = "The War Within Season 2\nBinds to Warband\n\"A small contraption able to specifically block the Underpin's incoming radio waves, preventing him from listening to his favorite gobcast.\"\nSell Price:" }
entries[233187] = { ["name"] = "Botanical Report", ["text"] = "Quest Item\nRequires level 80 to 80 ( 80)\n\"A botanical report detailing every plant, seed, and count of every item and their progress within Eco-Dome: Primus.\"" }
entries[233189] = { ["name"] = "Shield Technician Report", ["text"] = "Quest Item\nRequires level 80 to 80 ( 80)\n\"A report regarding the integrity of all shield generators within Eco-Dome: Primus. This report shows a myriad of tables and charts, as well as a long checklist of eco-dome quadrants.\"" }
entries[233190] = { ["name"] = "Wanderer Liu", ["text"] = "Binds to Warband\nUse: Teaches you how to summon and dismiss this companion.\nRight Click to summon and dismiss this companion.\nRequires level 1 to 90 ( 90)\nSell Price:" }
entries[233192] = { ["name"] = "Shadowguard Weapon", ["text"] = "Quest Item\n\"This scepter emits a dark energy that pulls upon your essence.\"" }
entries[233193] = { ["name"] = "Shadowguard Weapon", ["text"] = "Quest Item\n\"This blade is inscribed with the last known name of its owner: Betrayer.\"" }
entries[233194] = { ["name"] = "Shadowguard Weapon", ["text"] = "Quest Item\n\"The handle feels cold to touch as if it pulls from your life force.\"" }
entries[233195] = { ["name"] = "Pheromone Disperser", ["text"] = "Quest Item\nUse: Spray a pungent scent on anything in front of you. (3 Sec Cooldown)\n\"Used to spray pheromones on the creatures in the Oasis. Not to be used on yourself.\"" }
entries[233196] = { ["name"] = "Delver's Gob-Trotter Schematic: Gold", ["text"] = "Airship Schematic\nBinds when picked up\nUse: Unlocks this customization option for the Delver's Gob-Trotter at the Rostrum of Transformation." }
entries[233199] = { ["name"] = "Saturated Entropic Core", ["text"] = "Quest Item\n\"Ultra condensed energies contained in a tiny space.\"" }
entries[233202] = { ["name"] = "G.O.L.E.M, Jr.", ["text"] = "Binds when picked up\nUnique\nToy\nUse: Take control of the G.O.L.E.M. Jr. for 30 min. (1 Hour Cooldown)\n\"After the G.O.L.E.M went berserk, Pitz decided to make something smaller, more precise, and smarter.\"\nSell Price:" }
entries[233205] = { ["name"] = "Go-Go Juice", ["text"] = "Binds to Warband\nUse: Take a swig of Venture Co.'s\ndelicious energy beverage. Increase your movement speed by 1-60% for 12 sec.\n\nOnly usable in delves and outdoors in Khaz Algar. (1 Min Cooldown)\n\"Results may vary.\"\nSell Price:" }
entries[233207] = { ["name"] = "The Coward's Azure Target", ["text"] = "Cosmetic\nBinds to Warband\nBack\n\"You are literally putting a target on your back.\"\nUse: Add this appearance to your Warband collection.\nSell Price:" }
entries[233210] = { ["name"] = "Pungent Putrigill", ["text"] = "Binds to Warband\nUse: Waft this fish in a cone in front of you inflicting Putrigill Stench to up to 5 enemies.\n\nEnemies inflicted with Putrigill Stench take 5% increased damage from you for 20 sec. Can only be used in delves and outdoors in Khaz Algar. (1 Min Cooldown)\n\"A particularly stinky fish. Should not be bought or sold on the auction house.\"\nSell Price:" }
