entries[233240] = { ["name"] = "Polly Roger", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\n\nThis mount can use Ride Along.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The scourge of the slightly-northeastern seas, giant parrots like Polly can live for up to 2000 years. What a wonderful curse on your next of kin.\"\nSpecial Event:\nPlunderstorm" }
entries[233241] = { ["name"] = "Hooktalon", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\n\nThis mount can use Ride Along.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"Hooktalon once sailed with the Bloodsail Buccaneers, and later with the Blackwater Raiders, but he left to see what plunder he could find beyond the high seas.\"\nSpecial Event:\nPlunderstorm" }
entries[233242] = { ["name"] = "Royal Seafeather", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses your Giant Parrot. This mount changes depending on your Riding skill and location.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"The sharp beaks of these parrots are capable of breaking open large nuts with ease.\"\nSpecial Event:\nPlunderstorm" }
entries[233243] = { ["name"] = "Silver Tidestallion", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount. Can only be used underwater.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"This tidestallion and its silvery scales were drawn to the glint of plunder in your pocket.\"\nSpecial Event:\nPlunderstorm" }
entries[233246] = { ["name"] = "Gunk-Covered Thingy", ["text"] = "Binds when picked up\n\"Something's under all of this gunk. Angelo Rustbin at S.C.R.A.P. Headquarters will be interested in this.\"" }
