entries[233282] = { ["name"] = "Meeksi Rufflefur", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Rufflefurs are playful, clumsy and obsessed with cleanliness. This is a dangerous combination of traits.\"\nIn-Game Shop" }
entries[233283] = { ["name"] = "Meeksi Softpaw", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Softpaws provide a black tea that is ideal for an early morning jolt or staying awake late into the night.\"\nIn-Game Shop" }
entries[233284] = { ["name"] = "Meeksi Rollingpaw", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Rollingpaws are very proud of their tea bearing duties. They are always willing to provide a warm cup of tea to their travelling companions.\"\nIn-Game Shop" }
entries[233285] = { ["name"] = "Meeksi Teatuft", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Teatufts are known for their aromatic teas. However, their playful nature can result in an excess of spilled tea.\"\nIn-Game Shop" }
entries[233286] = { ["name"] = "Meeksi Brewthief", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Despite their mischievous and playful nature, these creatures make for loyal and dependable travelling companions.\"\nIn-Game Shop" }
