entries[233354] = { ["name"] = "Savage Alabaster Battle Turtle", ["text"] = "Binds to Warband\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon a rideable Savage Alabaster Battle Turtle. This mount swims fast and can't move very quickly on land, but it doesn't need to. It has cannons.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\nSell Price:\n\"Wisdom throughout the ages has led to a well-known saying, \"Nothing can outrun a cannon.\"\"\nTrading Post" }
