entries[233444] = { ["name"] = "Kaja'Cola X-Treme", ["text"] = "Binds when picked up\nUnique (5)\nUse: Increases movement speed by 50%, haste by 30%, and allows you to shovel twice as much trash from a S.C.R.A.P. Heap for 20 sec.\nRequires Renown Rank 7 with the Cartels of Undermine.\n\"3-in-1 energy drink, brake cleaner, and hair conditioner.\"\nSell Price:" }
entries[233445] = { ["name"] = "Kaja'Cola X-Treme Mega-Can", ["text"] = "Binds when picked up\nUnique (5)\nUse: Increases movement speed by 50%, haste by 30%, and allows you to shovel twice as much trash from a S.C.R.A.P. Heap for 1 min.\nRequires Renown Rank 16 with the Cartels of Undermine.\n\"Made with 100% recycled blue raspberry flavoring. Recognized as consumable in at least one jurisdiction.\"\nSell Price:" }
entries[233446] = { ["name"] = "Multi-Pack of Kaja'Cola", ["text"] = "Binds when picked up\nUnique (5)\nUse: Toss a round of Kaja'Cola X-Treme to up to 6 nearby players, plus an extra to yourself.\n\nKaja'Cola X-Treme :\nIncreases movement speed by 50%, haste by 30%, and allows you to shovel twice as much trash from a S.C.R.A.P. Heap for 20 sec.\nRequires Renown Rank 16 with the Cartels of Undermine.\n\"Buy in bulk, save an ultimately negligible amount of money!\"\nSell Price:" }
