entries[233489] = { ["name"] = "Prismatic Snapdragon", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount. This mount changes depending on your Riding skill and location.\nSummons and dismisses this mount.\nRequires level 1 to 90 ( 90)\nRequires Apprentice Riding\n\n\"Chameleonic creatures can oftentimes adapt their cells to match the color of the outside world. This snapdragon adopted this ability, but only to match the contents of their stomach; taking the phrase 'you are what you eat' to a whole new level.\"\nQuest:\nA Loyal Friend\nZone:\nSiren Isle" }
